{"query": "SELECT ?poet (COUNT(?book) AS ?bookCount) WHERE {
  ?poet a dbo:Poet .
  ?book a dbo:Book .
  ?book dbo:author ?poet .
}
GROUP BY ?poet
ORDER BY DESC(?bookCount)
LIMIT 1", "question": "Which poet wrote the most books?"}

{"query": "SELECT ?poet (COUNT(?book) AS ?bookCount) WHERE {
  ?book a dbo:Book .
  ?book dbo:author ?poet .
  ?poet a dbo:Person .
  {
    ?poet dbo:occupation dbo:Poet .
  } UNION {
    ?poet dct:subject dbc:Poets .
  }
}
GROUP BY ?poet
ORDER BY DESC(?bookCount)
LIMIT 1", "question": "Which poet wrote the most books?"}

{"query": "SELECT ?poet (COUNT(?book) AS ?bookCount) WHERE {
  ?book a dbo:Book .
  ?book dbo:author ?poet .
  ?poet dct:subject dbc:Poets .
}
GROUP BY ?poet
ORDER BY DESC(?bookCount)
LIMIT 1", "question": "Which poet wrote the most books?"}

{"query": "SELECT ?poet (COUNT(?book) AS ?bookCount) WHERE {
  ?book a dbo:Book .
  ?book dbo:author ?poet .
  ?poet a dbo:Person .
  FILTER EXISTS { ?poet a dbo:Poet }
}
GROUP BY ?poet
ORDER BY DESC(?bookCount)
LIMIT 1", "question": "Which poet wrote the most books?"}

{"query": "SELECT DISTINCT ?gangster WHERE {
  ?gangster dbo:occupation|dbp:occupation res:Gangster .
  OPTIONAL { ?gangster dbo:birthDate ?birthDate . }
  OPTIONAL { ?gangster dbp:birthDate ?birthDate2 . }
  OPTIONAL { ?gangster dbo:deathDate ?deathDate . }
  OPTIONAL { ?gangster dbp:deathDate ?deathDate2 . }

  BIND(COALESCE(?birthDate, ?birthDate2) AS ?birth)
  BIND(COALESCE(?deathDate, ?deathDate2) AS ?death)

  FILTER (
    (?birth <= "1933-12-31"^^xsd:date || !BOUND(?birth)) &&
    (?death >= "1920-01-01"^^xsd:date || !BOUND(?death))
  )
} LIMIT 100", "question": "Give me all gangsters from the prohibition era."}

